self.onmessage=function(r){for(var n=new Uint8ClampedArray(r.data.pixels),a=[new Uint32Array(256),new Uint32Array(256),new Uint32Array(256),new Uint32Array(256)],e=n.length/4,t=0,s=0;s<n.length;s+=4){var i=n[s],o=n[s+1],l=n[s+2];a[0][Math.round((i+o+l)/3)]++,a[1][i]++,a[2][o]++,a[3][l]++,t+=i+o+l}self.postMessage({histogram:a.map(function(r){return Array.from(r)}),total:e,sum:t})};